def bind(ctx: RequestContext, copilot: Copilot) -> Binding:
    """Grant authority: the one place a session becomes an agent principal.

    The intersection is computed here and handed to ``subset_for``, which checks it
    again. Computing it and then having the kernel type re-check the subset relation is
    the point: a future edit that computed a union instead would raise, not widen.
    """
    session_capabilities = ctx.principal.capabilities
    harness = ctx.principal.subset_for(copilot.harness_slug, session_capabilities & AGENT_SURFACE)
    specialists = {
        specialist: harness.subset_for(
            specialist.value, harness.capabilities & SPECIALIST_ALLOWLIST[specialist]
        )
        for specialist in COPILOT_SPECIALISTS[copilot]
    }
    return Binding(copilot=copilot, harness=harness, specialists=MappingProxyType(specialists))

def _visible_cases(ctx: RequestContext) -> Select[tuple[SupportCase]]:
    """Only operators may read across merchants; request filters can only narrow scope."""
    query = select(SupportCase).where(SupportCase.tenant_id == ctx.tenant_id)
    if ctx.principal.actor_type is not ActorType.OPERATOR:
        query = query.where(SupportCase.merchant_id == ctx.merchant_id)
    return query

async def probe(client: httpx.AsyncClient, name: str, url: str) -> dict[str, str]:
    if not url:
        return {"status": "unconfigured", "notice": "Health endpoint is not configured."}
    try:
        response = await client.get(url)
        body = response.json()
        if response.status_code != 200 or body.get("status") != "ok":
            return {"status": "unavailable", "notice": "Service reports an unhealthy state."}
        if name == "voice" and body.get("speech_available") is not True:
            return {"status": "degraded", "notice": "Gateway responds, but speech is unavailable."}
        if name == "worker":
            age = body.get("last_tick_seconds_ago")
            if (
                not isinstance(age, (int, float))
                or isinstance(age, bool)
                or not math.isfinite(age)
                or age < 0
            ):
                return {"status": "unknown", "notice": "No valid worker heartbeat evidence."}
        return {
            "status": "healthy",
            "notice": "Recent worker heartbeat."
            if name == "worker"
            else "Gateway responds and speech is available; no live audio turn tested.",
        }
    except httpx.HTTPError, ValueError, TypeError, AttributeError:
        return {"status": "unavailable", "notice": "Health check failed or timed out."}

def admission(request: Request, limits: Sequence[tuple[str, int, int]]) -> Iterator[None]:
    try:
        with request.app.state.workload.admit(limits):
            yield
    except WorkloadExceededError as exc:
        raise HTTPException(
            429,
            "Demo is busy. Please wait a minute and try again.",
            headers={"Retry-After": "60"},
        ) from exc

def verify_artifact(artifact: str, *, jwks: str | None = None) -> dict[str, Any]:
    """Verify with the deployment's public trust set, never a key carried by a token."""
    try:
        if not isinstance(artifact, str) or len(artifact) > 32768 or artifact.count(".") != 2:
            raise ReserveProofError("compact_authority_signature_required")
        ring = json.loads(
            jwks if jwks is not None else os.environ["RESERVE_PROVIDER_VERIFICATION_JWKS"]
        )
        token = JWS()
        token.allowed_algs = ["ES256"]
        token.deserialize(artifact)
        header = token.jose_header
        if (
            set(header) != {"alg", "kid", "typ"}
            or header.get("alg") != "ES256"
            or header.get("typ") != TYPE
        ):
            raise ReserveProofError("unsupported_authority_signature_profile")
        kid = header.get("kid")
        if not isinstance(kid, str) or kid in ring.get("revoked_kids", []):
            raise ReserveProofError("unknown_or_revoked_authority_key")
        keys = [k for k in ring["keys"] if k.get("kid") == kid]
        if len(keys) != 1:
            raise ReserveProofError("unknown_or_ambiguous_authority_key")
        key = keys[0]
        if key.get("kty") != "EC" or key.get("crv") != "P-256" or "d" in key:
            raise ReserveProofError("verification_key_must_be_public_p256")
        trust_path = os.environ.get("RESERVE_TRUST_CONFIG_PATH")
        if trust_path:
            verify_key(load_policy(trust_path), key)
        elif os.environ.get("RESERVE_SIGNER_MODE", "local") != "local":
            raise ReserveProofError("pinned_trust_policy_required")
        token.verify(JWK(**key), alg="ES256")
        claims = json.loads(token.payload)
        if not isinstance(claims, dict):
            raise ReserveProofError("authority_claims_not_object")
        if token.payload != canonicalize(claims):
            raise ReserveProofError("authority_payload_not_canonical")
        expected = {
            "version",
            "iss",
            "aud",
            "authority_id",
            "tenant_id",
            "merchant_id",
            "buyer_ref",
            "currency",
            "max_amount_minor",
            "per_purchase_limit_minor",
            "allowed_skus",
            "expires_at",
            "issued_at",
            "jti",
            "nonce",
            "provider_reference",
            "initial_epoch",
        }
        if claims.get("version") == 2:
            expected.add("buyer_consent_sha256")
            consent = claims.get("buyer_consent_sha256")
            if (
                not isinstance(consent, str)
                or len(consent) != 64
                or any(c not in "0123456789abcdef" for c in consent)
            ):
                raise ReserveProofError("authority_consent_digest_invalid")
        if set(claims) != expected or claims["iss"] != ISSUER or claims["aud"] != AUDIENCE:
            raise ReserveProofError("authority_issuer_audience_or_claims_invalid")
        if (
            type(claims["version"]) is not int
            or claims["version"] not in (1, 2)
            or type(claims["initial_epoch"]) is not int
            or claims["initial_epoch"] != 0
        ):
            raise ReserveProofError("authority_version_or_epoch_invalid")
        if type(claims["issued_at"]) is not int or claims["issued_at"] > time.time() + 30:
            raise ReserveProofError("authority_issue_time_invalid")
        for name in ("authority_id", "tenant_id", "merchant_id", "jti", "nonce"):
            uuid.UUID(claims[name])
        if not isinstance(claims["buyer_ref"], str) or not claims["buyer_ref"]:
            raise ReserveProofError("authority_buyer_missing")
        if not isinstance(claims["provider_reference"], str) or not claims[
            "provider_reference"
        ].startswith("sim_reserve_"):
            raise ReserveProofError("simulator_reference_required")
        for name in ("max_amount_minor", "per_purchase_limit_minor"):
            value = claims[name]
            if value is not None and (type(value) is not int or value <= 0):
                raise ReserveProofError("authority_amount_invalid")
        if claims["max_amount_minor"] is None:
            raise ReserveProofError("authority_capacity_required")
        if (
            claims["per_purchase_limit_minor"] is not None
            and claims["per_purchase_limit_minor"] > claims["max_amount_minor"]
        ):
            raise Reserve

class BrowserMount:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http" or not scope["path"].startswith("/api/"):
            await self.app(scope, receive, send)
            return
        request = Request(scope, receive)
        settings = request.app.state.settings
        parts = scope["path"].split("/", 3)
        surface = parts[2] if len(parts) > 2 else ""
        path = parts[3] if len(parts) > 3 else ""

        async def refuse(status: int, detail: str) -> None:
            await JSONResponse(
                {"detail": detail}, status_code=status, headers={"Cache-Control": "no-store"}
            )(scope, receive, send)

        if not settings.demo_routes_enabled or os.environ.get("BROWSER_DEMO_ENABLED") != "true":
            await refuse(404, "Browser demo is disabled.")
            return
        # Deployment owns this origin. Do not trust arbitrary forwarded browser headers.
        origin = os.environ.get("BROWSER_ORIGIN", "http://localhost:8000").rstrip("/")
        origins = {origin} | {
            value.strip().rstrip("/")
            for value in os.environ.get("BROWSER_ADDITIONAL_ORIGINS", "").split(",")
            if value.strip()
        }
        if any(
            urlsplit(value).scheme != "https"
            and not (
                urlsplit(value).scheme == "http"
                and urlsplit(value).hostname in {"localhost", "127.0.0.1", "::1"}
            )
            for value in origins
        ):
            await refuse(503, "HTTPS is required outside local development.")
            return
        if request.method not in {"GET", "HEAD"} and request.headers.get("origin") not in origins:
            await refuse(403, "Same-origin browser request required.")
            return
        if surface == "voice" and path == "ticket":
            await self.voice(request, origin, receive, send)
            return
        if surface not in SURFACES or not path or any(p in {".", ".."} for p in path.split("/")):
            await refuse(404, "Unknown browser surface.")
            return
        if path == "voice/ticket":
            await self.voice(request, origin, receive, send, surface=surface)
            return
        role, cookie_name = SURFACES[surface]
        if surface == "platform" and os.environ.get("OPERATOR_DEMO_OPEN_ACCESS") != "true":
            await refuse(404, "Open operator demo is disabled.")
            return
        # Infrastructure and fixture control are never capabilities of this browser demo.
        group = path.split("/", 1)[0]
        if path != "session" and (
            group in {"demo", "scenario", "webhooks", "mcp"}
            or (group == "protocols" and surface != "platform")
            or path.startswith("reserve/simulator/")
            or (surface != "platform" and group in {"ops", "review"})
            or (
                surface == "platform"
                and (
                    group
                    not in {
                        "ops",
                        "review",
                        "inspector",
                        "audit",
                        "merchants",
                        "protocols",
                        "checkouts",
                        "refunds",
                        "config",
                    }
                    or request.method not in {"GET", "HEAD"}
                    and not (
                        path in {"ops/safe-mode", "ops/agent/turn"}
                        or (
                            request.method == "POST"
                            and path in {"protocols/probe", "protocols/enable-demo"}
                        )
                        or (
                            request.method == "POST"
                            and len(path.split("/")) == 4
                            and path.startswith("ops/outbox/")
                            and path.endswith("/revive")
                        )
                    )
                )
            )
        ):
            await refuse(403, "This operation is outside this demo surface.")
            return
        token = unquote(request.cookies[cookie_name]) if cookie_name in request.cookies else None
        added_cookies: list[bytes] = []
        secure = "; Secure" if origin.startswith("https://") else ""
        cookie_path = "/" if surface == "commerce" else f"/api/{surface}"

